import Foundation

/// Loads the bundled `airports.json` and answers lookups like "which airport is SFO?".
///
/// The JSON is generated by `scripts/build_airports.py` from OurAirports data.
nonisolated struct AirportStore: Sendable {
    let airports: [Airport]
    private let byCode: [String: Airport]

    init(airports: [Airport]) {
        self.airports = airports
        // A dictionary gives instant lookup by code instead of scanning 1,000+ airports.
        self.byCode = Dictionary(airports.map { ($0.iata, $0) },
                                 uniquingKeysWith: { first, _ in first })
    }

    /// Reads airports.json from the app bundle (the files shipped inside the app).
    static func loadBundled(from bundle: Bundle = .main) throws -> AirportStore {
        guard let url = bundle.url(forResource: "airports", withExtension: "json") else {
            throw LoadError.fileMissing
        }
        let data = try Data(contentsOf: url)
        // JSONDecoder matches JSON keys to Airport's property names — that's what Codable buys us.
        let airports = try JSONDecoder().decode([Airport].self, from: data)
        return AirportStore(airports: airports)
    }

    func airport(code: String) -> Airport? {
        byCode[code.uppercased()]
    }

    enum LoadError: Error {
        case fileMissing
    }
}
